import base64, os
files = {}
files['app/api/routes_portfolio_analysis.py'] = base64.b64decode('')
files['app/ingestion/portfolio_claims.py'] = base64.b64decode('')
files['app/ingestion/portfolio_members.py'] = base64.b64decode('')

for path, content in files.items():
    os.makedirs(os.path.dirname(path), exist_ok=True) if os.path.dirname(path) else None
    with open(path, "wb") as fh:
        fh.write(content)
    print(f"wrote {path} ({len(content)} bytes)")
print("Done.")
